#include "fstr/scene_window.hpp"
#include <iostream>
#include <stdexcept>
#include <cstring>
using namespace fstr;
void check(bool v,const char*m){if(!v)throw std::runtime_error(m);}
std::shared_ptr<SceneAnalysis> frame(double strength){auto f=std::make_shared<SceneAnalysis>();f->width=2;f->height=1;f->scene.resize(2);for(auto&w:f->scene)w[0]=.8;PersonAnalysis p;p.box={.1,.1,.3,.5};p.descriptor={1.1,1,.8};p.detection_confidence=.95;p.mask={.5,.5};p.toning_support={.6,.6};p.toning_strength=strength;p.samples={{{.2,.3,.4},.8}};f->people.push_back(p);return f;}
int main(){try{auto a=frame(.1),b=frame(.9),c=frame(.2);auto out=stabilize_scene_window({{-1,a},{0,b},{1,c}});check(out->people[0].toning_strength==.2,"Two-sided scalar median failed");check(out->people[0].mask==b->people[0].mask&&out->people[0].toning_support==b->people[0].toning_support&&out->scene==b->scene,"Other-frame geometry was transferred");check(out->people[0].samples.size()==3&&b->people[0].samples.size()==1,"Reference pooling mutated raw cache");auto reverse=stabilize_scene_window({{1,c},{0,b},{-1,a}});check(reverse->people[0].toning_strength==.2,"Window order affected scalar");check(stabilize_scene_window({{0,b},{1,c}})->people[0].toning_strength==.9,"One-sided extrapolation was forced");c->people[0].descriptor={.1,.1,4};check(stabilize_scene_window({{-1,a},{0,b},{1,c}})->people[0].toning_strength==.9,"Wrong person transferred");c=frame(.2);c->people.push_back(c->people[0]);check(stabilize_scene_window({{-1,a},{0,b},{1,c}})->people[0].toning_strength==.9,"Ambiguous people forced a match");bool rejected=false;try{stabilize_scene_window({{0,b},{0,a}});}catch(const std::invalid_argument&){rejected=true;}check(rejected,"Duplicate offsets accepted");auto no_people=frame(.3);no_people->people.clear();check(stabilize_scene_window({{-1,a},{0,no_people},{1,a}})->people.empty(),"Missing person was invented");std::cout<<"PASS explicit scalar window, immutable geometry, order, one-sided fallback, identity rejection, ambiguity and missing people\\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
